    const reject=async(label,source,code,engine='rust',optionsOverride={})=>{const file=retain('outputs/protected-'+label+'.pdf',old),before=fileSha(file),names=fs.readdirSync(path.dirname(file)).sort(),request=exportRequestFor(source,'pdf',engine,documents,file);request.arguments.overwrite=true;request.arguments.options=optionsOverride;assert.equal(lifecycle.errorBody(await call(request.name,request.arguments,90000)).error_code,code);assert.equal(fileSha(file),before,'Rejected export replaced the old actual PDF');assert.deepEqual(fs.readdirSync(path.dirname(file)).sort(),names,'Rejected export left sidecars');report.protectedTargets.push({label,path:path.relative(evidence,file),sha256:before,bytes:old.length,errorCode:code,preserved:true});};
    for(const testCase of negativeCases()){retain('inspection/negative-'+testCase.label+'.dsl',testCase.source);const raw=await call('readmd_math',{operation:'parse',source:testCase.source,dialect:'dsl',display:true,font_size:12,layout_width:300});if(testCase.sourceOnly){const value=payload(raw);assert.equal(value.document.source,testCase.source);assert.equal(value.document.revision,sha(testCase.source));assert.equal(value.vector_preview,null);assert.equal(value.preview_supported,false);assert(value.document.diagnostics.some(row=>row.code===testCase.code&&row.from===0&&row.to===testCase.source.length));}else assert.equal(lifecycle.errorBody(raw).error_code,testCase.code);await reject(testCase.label,lifecycle.fence(testCase.source),testCase.code);}
