    await reject('baseline-local','<!-- readmd:layout v1 {"id":"unit-baseline-negative","text":{"baselineShiftPt":3},"paragraph":{"lineSpacing":{"mode":"exact","pt":18}}} -->\n\nProtected ordinary paragraph.\n','publication_baseline_unsupported','typst');check('Negative directions/schema/budget and nonzero baseline preserve existing actual PDFs',{requests:report.protectedTargets.length});
